package net.minecraft.server; import java.util.*; import net.minecraft.server.level.ServerPlayer; public class MinecraftServer {public final PlayerList players=new PlayerList(); public final List<String> cmds=new ArrayList<>(); public PlayerList getPlayerList(){return players;} public Commands getCommands(){return new Commands(cmds);} public Source createCommandSourceStack(){return new Source();} public static class PlayerList{public List<ServerPlayer> players=new ArrayList<>(); public List<ServerPlayer> getPlayers(){return players;}} public static class Source{public Source withSuppressedOutput(){return this;}} public static class Commands{List<String> cmds;public Commands(List<String> cmds){this.cmds=cmds;} public void performPrefixedCommand(Source source,String command){cmds.add(command);}}}